// Inlines packages/agent/prompts/*.md into packages/agent/src/prompts.gen.ts, so the prompts ship inside any bundle
// (the `bun build --compile` CLI binary has no prompts folder next to it). `--check` fails when the generated file is
// stale (part of `bun run check`); `--write` regenerates it. The .md files stay the source of truth.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "packages", "agent", "prompts");
const out = join(import.meta.dirname, "..", "packages", "agent", "src", "prompts.gen.ts");

export function generate(): string {
  const entries = readdirSync(dir)
    .filter((f) => f.endsWith(".md"))
    .sort()
    .map((f) => `  ${JSON.stringify(f.slice(0, -3))}: ${JSON.stringify(readFileSync(join(dir, f), "utf8"))},`);
  return `// Generated by scripts/prompts-gen.ts from packages/agent/prompts/*.md — do not edit; run \`bun run prompts:write\`.\nexport const PROMPTS: Readonly<Record<string, string>> = {\n${entries.join("\n")}\n};\n`;
}

const mode = process.argv[2];
if (mode === "--write") {
  writeFileSync(out, generate());
  process.stdout.write("prompts: written\n");
} else if (mode === "--check") {
  let current = "";
  try {
    current = readFileSync(out, "utf8");
  } catch {
    // Missing counts as stale.
  }
  if (current !== generate()) {
    process.stderr.write("prompts: packages/agent/src/prompts.gen.ts is stale: run `bun run prompts:write`\n");
    process.exit(1);
  }
  process.stdout.write("prompts: up to date\n");
}
